"""RoboPaint lettering: observed geometry, pressure calibration, then scribe paths.
All actions use the public Robot client. No simulator state is accessed.
"""
import sys,json,time,os
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT=Path('/app/output'); Q=np.array([0.,1.,0.,0.]); Z=.0202
class Writer:
 def __init__(self):
  self.r=Robot();self.obs=self.r.get_obs(cameras=[]);self.p=self.obs.group('tcp_pose',now=True);self.seq=int(time.time())
 def send(self,pts,note='',cams=['practice_cam'],frames=False):
  pts=np.asarray(pts);out=None
  for a in range(0,len(pts),180):
   batch=pts[a:a+180]; before=self.r.status();np.save(OUT/f'command_{self.seq}.npy',batch)
   try: out=self.r.submit('ee_pose',batch,dt=.05,video='frames' if frames else 'none',video_fps=20,cameras=cams,note=note)
   except Exception:
    self.r.wait_ready();print('Service interrupted; before/after',before,self.r.status(),flush=True);raise
   out.save(str(OUT/f'run_{self.seq}'))
   for c,im in out.last.items():Image.fromarray(im).save(OUT/f'latest_{c}.png')
   fails=sum(x.get('ik_failures',0) for x in out.meta.get('plan',[]));print(note,'rows',len(batch),'fail',fails,'tip',out.group('tcp_pose',now=True)[:3],'left',out.meta.get('time_left_s'),flush=True)
   self.seq+=1;self.p=out.group('tcp_pose',now=True)
   if fails or out.stopped:raise RuntimeError('Motion incomplete')
  return out
 def move(self,xyz,q=None,speed=.04,hold=.3,note='move'):
  q=Q if q is None else q;target=np.r_[xyz,q];n=max(1,int(np.ceil(np.linalg.norm(target[:3]-self.p[:3])/speed/.05)))
  pts=[np.r_[self.p[:3]+(target[:3]-self.p[:3])*t,q] for t in np.linspace(0,1,n+1)[1:]];pts +=[target]*int(hold/.05)
  return self.send(pts,note)
 def park(self):
  self.move([self.p[0],self.p[1],.07]);self.move([-.22,0,.18]);o=self.r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam'],depth=True);o.save(str(OUT/'observed'))
  for c,a in o.last.items():Image.fromarray(a).save(OUT/f'latest_{c}.png')
 def line(self,start,end,depth,speed=.005,q=None):
  q=Q if q is None else q
  self.move([*start,Z+.005],q);self.move([*start,Z-depth],q,speed=.003,hold=.5)
  n=int(np.ceil(np.linalg.norm(np.array(end)-start)/speed/.05));pts=[np.r_[np.array(start)+(np.array(end)-start)*t,Z-depth,q] for t in np.linspace(0,1,n+1)[1:]];pts +=[pts[-1]]*10
  out=self.send(pts,f'calibration depth {depth}',frames=True);self.move([*end,Z+.005],q,speed=.003);return out
if __name__=='__main__':
 w=Writer();mode=sys.argv[1]
 if mode=='calibrate':
  w.move([-.10,.1488,.07]);w.move([-.10,.1488,.025],speed=.01,hold=1);w.move([-.10,.1488,.07])
  for i,d in enumerate([.0001,.0003,.0006,.001,.0015,.002,.003,.004]):
   w.line([-.035,-.148-i*.010],[-.065,-.148-i*.010],d)
  w.park()
 elif mode=='park':w.park()
PY
